package lifequest.analytics;

import lifequest.database.QuestDAO;
import lifequest.model.User;
import lifequest.ui.Style;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;

public class AnalyticsPanel extends JPanel {
    public AnalyticsPanel(User user){setBackground(Style.BACKGROUND);setLayout(new BorderLayout(18,18));setBorder(new EmptyBorder(28,30,28,30));
        JPanel head=new JPanel();head.setOpaque(false);head.setLayout(new BoxLayout(head,BoxLayout.Y_AXIS));head.add(Style.title("Your Progress"));JLabel sub=Style.label("Small improvements become big achievements.");sub.setForeground(Style.MUTED);head.add(Box.createVerticalStrut(5));head.add(sub);add(head,BorderLayout.NORTH);
        QuestDAO dao=new QuestDAO();int completed=dao.completedCount(user.getId()),xp=dao.totalXp(user.getId());JPanel cards=new JPanel(new GridLayout(1,4,12,12));cards.setOpaque(false);cards.add(stat("QUESTS COMPLETED",String.valueOf(completed),Style.ACCENT));cards.add(stat("XP EARNED",String.valueOf(xp),Style.SUCCESS));cards.add(stat("CURRENT LEVEL",String.valueOf(user.getLevel()),Style.ACCENT_BLUE));cards.add(stat("COINS",String.valueOf(user.getCoins()),new Color(255,190,92)));
        JPanel center=new JPanel(new GridLayout(1,2,16,16));center.setOpaque(false);center.add(progressCard(user));center.add(weeklyCard(completed));JPanel body=new JPanel(new BorderLayout(15,15));body.setOpaque(false);body.add(cards,BorderLayout.NORTH);body.add(center,BorderLayout.CENTER);add(body,BorderLayout.CENTER);
    }
    private JPanel stat(String name,String value,Color accent){JPanel p=Style.card();p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel n=Style.label(name);n.setForeground(Style.MUTED);n.setFont(new Font("Segoe UI",Font.BOLD,11));JLabel v=Style.title(value);v.setForeground(accent);v.setFont(new Font("Segoe UI",Font.BOLD,29));p.add(n);p.add(Box.createVerticalStrut(12));p.add(v);p.add(Box.createVerticalStrut(5));JLabel t=Style.label("Your journey continues");t.setForeground(Style.MUTED);t.setFont(new Font("Segoe UI",Font.PLAIN,11));p.add(t);return p;}
    private JPanel progressCard(User u){JPanel p=Style.card();p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));p.add(Style.title("Next level"));JLabel l=Style.label("Level "+u.getLevel()+" Adventurer");l.setForeground(Style.MUTED);p.add(Box.createVerticalStrut(10));p.add(l);JProgressBar bar=new JProgressBar(0,100);bar.setValue(Math.floorMod(u.getXp(),100));bar.setStringPainted(true);bar.setString(Math.floorMod(u.getXp(),100)+" / 100 XP");bar.setForeground(Style.ACCENT);bar.setBackground(new Color(29,37,69));bar.setBorderPainted(false);bar.setMaximumSize(new Dimension(Integer.MAX_VALUE,25));p.add(Box.createVerticalStrut(14));p.add(bar);p.add(Box.createVerticalStrut(24));p.add(Style.title("Character stats"));p.add(Box.createVerticalStrut(14));line(p,"Health",u.getHealth(),new Color(255,105,145));line(p,"Focus",u.getFocus(),Style.ACCENT_BLUE);line(p,"Discipline",u.getDiscipline(),Style.SUCCESS);line(p,"Strength",u.getStrength(),new Color(255,190,92));return p;}
    private void line(JPanel p,String name,int value,Color color){JPanel r=new JPanel(new BorderLayout(8,0));r.setOpaque(false);r.setMaximumSize(new Dimension(Integer.MAX_VALUE,24));JLabel n=Style.label(name);n.setForeground(Style.MUTED);n.setPreferredSize(new Dimension(80,20));JProgressBar b=new JProgressBar(0,100);b.setValue(Math.max(0,Math.min(100,value)));b.setForeground(color);b.setBackground(new Color(29,37,69));b.setBorderPainted(false);r.add(n,BorderLayout.WEST);r.add(b,BorderLayout.CENTER);r.add(Style.label(String.valueOf(value)),BorderLayout.EAST);p.add(r);p.add(Box.createVerticalStrut(8));}
    private JPanel weeklyCard(int completed){JPanel p=Style.card();p.setLayout(new BorderLayout(8,15));p.add(Style.title("Quest milestones"),BorderLayout.NORTH);JPanel rows=new JPanel(new GridLayout(4,1,8,8));rows.setOpaque(false);rows.add(milestone("First quest completed",completed>=1));rows.add(milestone("5 quests completed",completed>=5));rows.add(milestone("10 quests completed",completed>=10));rows.add(milestone("Level 5 adventurer",false));p.add(rows,BorderLayout.CENTER);JLabel note=Style.label("Keep completing quests to unlock more milestones.");note.setForeground(Style.MUTED);p.add(note,BorderLayout.SOUTH);return p;}
    private JPanel milestone(String text,boolean done){JPanel r=Style.card();r.setLayout(new BorderLayout(10,0));JLabel icon=Style.label(done?"✓":"✧");icon.setForeground(done?Style.SUCCESS:Style.ACCENT);icon.setFont(new Font("Segoe UI",Font.BOLD,20));r.add(icon,BorderLayout.WEST);JLabel t=Style.label(text);t.setForeground(done?Style.TEXT:Style.MUTED);r.add(t,BorderLayout.CENTER);return r;}
}